insert into public.massnahmen (id, thema_id, partei_id, land, beschreibung, ursachen_ids, instrument_id, wirksamkeit, umsetzbarkeit,
  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft, nebenwirkungen) values
  (10772, 42, 11, null, 'Einkommensteuertarif schrittweise senken, Grundfreibetrag erhöhen, Grenze für den Spitzensteuersatz anheben', '{4201}', 10761, 2, 1, null, 'Mildert den steilen Progressionsverlauf bei mittleren Einkommen, an dem die kalte Progression besonders wirkt. Dagegen: einmalige Änderung ohne Indexierung, Entlastung absolut v. a. bei höheren Einkommen, hohe Ausfälle ohne Finanzierung.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=14', null, 'gemischt', '2026-10-22', false, true, 'blind', null),
  (10773, 42, 11, null, 'Einkommensteuertarif regelmäßig an die Inflation anpassen, um die kalte Progression auszugleichen', '{4201}', 10759, 3, 3, null, 'Setzt direkt an der kalten Progression an; Schweiz, USA, Kanada, Belgien u. a. indexieren automatisch, Simulationen zeigen weitgehenden Ausgleich. Dagegen: Einnahmeausfall gegenüber Status quo und weniger Budgetspielraum; einfaches Bundesgesetz mit Bundesratszustimmung.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=14', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2016/heft/10/beitrag/moeglichkeiten-zur-kompensation-der-kalten-progression-wirkung-in-oesterreich.html', 'belegt', '2026-10-22', false, true, 'blind', null),
  (10774, 42, 11, null, 'Freibeträge bei der Erbschaftsteuer deutlich erhöhen', '{4203}', 10770, 0, 3, null, 'Setzt an der Erbschaftsteuer an, senkt aber deren Aufkommen und verstärkt damit das Übergewicht von Lohn- und Umsatzsteuer. Für einzelne Erben (Eigenheim) entlastend; rechtlich einfach umsetzbar.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=34', null, 'belegt', '2026-10-22', false, true, 'blind', null),
  (10775, 42, 11, null, 'Kassensturz beim Bund, alle Ausgaben und Subventionen hinterfragen, Ausgaben die ihr Ziel verfehlen entfallen lassen', '{4202}', 10765, 2, 2, null, 'Finanzhilfen und Steuervergünstigungen des Bundes umfassen dreistellige Milliardenbeträge, Abbau senkt das Defizit spürbar. Dagegen: Einsparziele bleiben oft unbestimmt, viele Posten sind politisch und rechtlich gebunden.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=77', null, 'gemischt', '2026-10-22', false, true, 'blind', null),
  (10776, 42, 11, null, 'Maastricht-Kriterien (Schuldenstand, Defizit) verbindlich halten, Verstöße über automatisiertes Defizitverfahren sanktionieren', '{4202}', null, 1, 1, null, 'Verbindliche EU-Defizitregeln können Haushaltsdisziplin stärken. Dagegen: Regeln gelten bereits, ein automatisiertes Verfahren erfordert EU-Beschlüsse, die Deutschland nicht allein treffen kann.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=78', null, 'gemischt', '2026-10-22', false, true, 'blind', null),
  (10777, 42, 12, null, 'Einkommensteuertarif so entlasten, dass die große Mehrheit der Steuerpflichtigen profitiert; Spitzeneinkommen und -vermögen stärker beteiligen.', '{4201}', 10762, 2, 2, null, 'Senkt die Belastung der Mehrheit der Beschäftigten und ist teilweise gegenfinanziert. Dagegen: keine dauerhafte Inflationsanpassung, Ausweichreaktionen hoher Einkommen mindern die Gegenfinanzierung.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=23', null, 'gemischt', '2026-10-22', false, true, 'blind', null),
  (10778, 42, 12, null, 'Schuldenregel im Grundgesetz reformieren, damit Investitionen nicht behindert werden; mehr Kreditspielraum.', '{4202}', 10764, 1, 1, null, 'Kann Investitionsstau abbauen und Wachstum stützen; IWF verweist auf Investitionsverdrängung durch starre Regeln. Dagegen: erhöht Defizit und Zinslast unmittelbar; erfordert Grundgesetzänderung mit Zweidrittelmehrheit, EU-Regeln gelten weiter.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=17', 'https://www.imf.org/-/media/files/publications/sdn/2018/sdn1804-on-second-generation-fiscal-rules.pdf.md', 'gemischt', '2026-10-22', false, true, 'blind', null),
  (10779, 42, 12, null, 'Vermögensteuer für sehr hohe Vermögen wieder einführen und so Einnahmen erhöhen.', '{4203}', 10768, 2, 2, null, 'Erhöht den Anteil vermögensbezogener Steuern; DIW schätzt je nach Ausgestaltung zweistellige Milliardenbeträge. Dagegen: Ausweichreaktionen, Bewertungsaufwand und Verfassungsvorgaben zur Bewertung; Aufkommen fließt den Ländern zu.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=19', 'https://www.diw.de/de/diw_01.c.1002952.de/nachrichten/es_gibt_bessere_wege__vermoegen_zu_besteuern.html', 'gemischt', '2026-10-22', false, true, 'blind', null),
  (10780, 42, 12, null, 'Mindestbesteuerung für große Betriebsvermögen bei Erbschaften und Schenkungen einführen.', '{4203}', 10769, 2, 3, null, 'Große Betriebsvermögen werden weitgehend steuerfrei übertragen, Schätzungen nennen Ausfälle in Milliardenhöhe; Stundung kann Liquiditätsprobleme mildern. Dagegen: Unternehmensverbände warnen vor Investitionsfolgen, Ausweichgestaltungen möglich.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=19', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2016/heft/6/beitrag/die-demontage-der-erbschaftsteuer.html', 'gemischt', '2026-10-22', false, true, 'blind', null),
  (10781, 42, 12, null, 'Finanztransaktionssteuer einführen, weil Finanztransaktionen bisher nicht besteuert werden.', '{4203}', 10771, 1, 2, null, 'Besteuert bisher steuerfreie Kapitaltransaktionen; Frankreich und Italien erheben sie. Dagegen: dortige Einnahmen blieben unter den Prognosen, Handel weicht aus; national einführbar, Bemessungsgrundlage strittig.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=19', 'https://articlegateway.com/index.php/JAF/article/view/6562', 'gemischt', '2026-10-22', false, true, 'blind', null),
  (10782, 42, 13, null, 'Arbeitnehmerpauschbetrag in der Einkommensteuer auf mindestens 1.500 Euro anheben.', '{4201}', null, 1, 3, null, 'Der Pauschbetrag ist nicht indexiert; eine Anhebung gleicht Inflation für Beschäftigte teilweise aus und vereinfacht. Dagegen: einmaliger Schritt, Wirkung je Person gering.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=74', null, 'offen', '2026-10-22', false, true, 'blind', null),
  (10783, 42, 13, null, 'Schuldenbremse reformieren: Kredite in dem Umfang zulassen, wie der Staat investiert.', '{4202}', 10764, 1, 1, null, 'Kann Investitionsstau abbauen und Wachstum stützen; IWF verweist auf Investitionsverdrängung durch starre Regeln. Dagegen: erhöht Defizit und Zinslast unmittelbar; erfordert Grundgesetzänderung mit Zweidrittelmehrheit, EU-Regeln gelten weiter.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=36', 'https://www.imf.org/-/media/files/publications/sdn/2018/sdn1804-on-second-generation-fiscal-rules.pdf.md', 'gemischt', '2026-10-22', false, true, 'blind', null),
  (10784, 42, 13, null, 'Steuerschlupflöcher schließen, um den Haushalt zu entlasten.', '{4202}', null, 1, 2, null, 'Schließen von Steuerschlupflöchern kann Mehreinnahmen bringen. Dagegen: ohne Benennung konkreter Regelungen bleiben Umfang und Wirkung unbestimmt.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=37', null, 'offen', '2026-10-22', false, true, 'blind', null),
  (10785, 42, 13, null, 'Klima- und umweltschädliche Subventionen abbauen.', '{4202}', 10765, 2, 2, null, 'Finanzhilfen und Steuervergünstigungen des Bundes umfassen dreistellige Milliardenbeträge, Abbau senkt das Defizit spürbar. Dagegen: Einsparziele bleiben oft unbestimmt, viele Posten sind politisch und rechtlich gebunden.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=37', null, 'gemischt', '2026-10-22', false, true, 'blind', null),
  (10786, 42, 13, null, 'Verwaltung durch weitere Digitalisierung verschlanken, um den Haushalt zu entlasten.', '{4202}', 10766, 1, 2, null, 'Senkt Personal- und Verwaltungskosten auf längere Sicht. Dagegen: Personalausgaben sind nur ein kleiner Teil des Bundeshaushalts, Digitalisierung kostet zunächst; Einsparungen kaum untersucht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=37', null, 'offen', '2026-10-22', false, true, 'blind', null),
  (10787, 42, 13, null, 'Erbschaftsteuer reformieren mit personenbezogenem Lebensfreibetrag und Ausnahmen für sehr große Erbschaften streichen.', '{4203}', 10769, 2, 3, null, 'Große Betriebsvermögen werden weitgehend steuerfrei übertragen, Schätzungen nennen Ausfälle in Milliardenhöhe; Stundung kann Liquiditätsprobleme mildern. Dagegen: Unternehmensverbände warnen vor Investitionsfolgen, Ausweichgestaltungen möglich.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=73', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2016/heft/6/beitrag/die-demontage-der-erbschaftsteuer.html', 'gemischt', '2026-10-22', false, true, 'blind', null),
  (10788, 42, 14, null, 'Einkommensteuer-Freibeträge und Eckwerte automatisch an die Preisentwicklung anpassen', '{4201}', 10759, 3, 3, null, 'Setzt direkt an der kalten Progression an; Schweiz, USA, Kanada, Belgien u. a. indexieren automatisch, Simulationen zeigen weitgehenden Ausgleich. Dagegen: Einnahmeausfall gegenüber Status quo und weniger Budgetspielraum; einfaches Bundesgesetz mit Bundesratszustimmung.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=14', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2016/heft/10/beitrag/moeglichkeiten-zur-kompensation-der-kalten-progression-wirkung-in-oesterreich.html', 'belegt', '2026-10-22', false, true, 'blind', null),
  (10789, 42, 14, null, 'Grundfreibetrag schrittweise um mindestens 1.000 Euro anheben', '{4201}', null, 1, 3, null, 'Höherer Grundfreibetrag entlastet alle Steuerpflichtigen und gleicht einen Teil der kalten Progression aus. Dagegen: einmaliger, mäßiger Schritt ohne dauerhafte Anpassung.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=14', null, 'belegt', '2026-10-22', false, true, 'blind', null),
  (10790, 42, 14, null, 'Einkommensteuertarif als linear-progressiver Chancentarif, der den Mittelstandsbauch beseitigt', '{4201}', 10761, 2, 1, null, 'Mildert den steilen Progressionsverlauf bei mittleren Einkommen, an dem die kalte Progression besonders wirkt. Dagegen: einmalige Änderung ohne Indexierung, Entlastung absolut v. a. bei höheren Einkommen, hohe Ausfälle ohne Finanzierung.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=14', null, 'gemischt', '2026-10-22', false, true, 'blind', null),
  (10791, 42, 14, null, 'Spitzensteuersatz erst bei höherem Einkommen greifen lassen (Bindung an die Beitragsbemessungsgrenze)', '{4201}', 10761, 2, 1, null, 'Mildert den steilen Progressionsverlauf bei mittleren Einkommen, an dem die kalte Progression besonders wirkt. Dagegen: einmalige Änderung ohne Indexierung, Entlastung absolut v. a. bei höheren Einkommen, hohe Ausfälle ohne Finanzierung.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=14', null, 'gemischt', '2026-10-22', false, true, 'blind', null),
  (10792, 42, 14, null, 'Schuldenbremse im Grundgesetz einhalten', '{4202}', 10763, 2, 3, null, 'Fiskalregeln gehen laut IWF mit niedrigeren Defiziten einher, besonders bei verbindlicher Ausgestaltung. Dagegen: kausaler Effekt umstritten, Regeln drücken oft Investitionen; geltendes Recht, daher leicht umsetzbar.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=35', 'https://www.imf.org/-/media/files/publications/sdn/2018/sdn1804-on-second-generation-fiscal-rules.pdf.md', 'gemischt', '2026-10-22', false, true, 'blind', null),
  (10793, 42, 14, null, 'Subventionen zurückfahren, bis Finanzhilfen und Steuerermäßigungen zur Wertschöpfung passen', '{4202}', 10765, 2, 2, null, 'Finanzhilfen und Steuervergünstigungen des Bundes umfassen dreistellige Milliardenbeträge, Abbau senkt das Defizit spürbar. Dagegen: Einsparziele bleiben oft unbestimmt, viele Posten sind politisch und rechtlich gebunden.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=36', null, 'gemischt', '2026-10-22', false, true, 'blind', null),
  (10794, 42, 14, null, 'Bundesausgaben stärker auf die originären Aufgaben des Bundes beschränken', '{4202}', null, 1, 3, null, 'Begrenzung auf Kernaufgaben kann Ausgaben senken. Dagegen: unbestimmt, welche Ausgaben entfallen; viele Bundesausgaben sind gesetzlich gebunden.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=36', null, 'offen', '2026-10-22', false, true, 'blind', null),
  (10795, 42, 14, null, 'Stellenzahl in der Bundesverwaltung außerhalb der Sicherheitsbehörden deutlich reduzieren', '{4202}', 10766, 1, 2, null, 'Senkt Personal- und Verwaltungskosten auf längere Sicht. Dagegen: Personalausgaben sind nur ein kleiner Teil des Bundeshaushalts, Digitalisierung kostet zunächst; Einsparungen kaum untersucht.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=37', null, 'offen', '2026-10-22', false, true, 'blind', null),
  (10796, 42, 14, null, 'Staatsbeteiligungen veräußern', '{4202}', null, 1, 2, null, 'Bringt einmalige Erlöse, die Schulden tilgen können. Dagegen: kein Beitrag zum strukturellen Defizit, entgangene Dividenden, Erlöse hängen vom Marktumfeld ab.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=36', null, 'offen', '2026-10-22', false, true, 'blind', null),
  (10797, 42, 14, null, 'Freibeträge der Erbschaft- und Schenkungsteuer automatisch an die Inflationsrate anpassen', '{4203}', 10770, 0, 3, null, 'Setzt an der Erbschaftsteuer an, senkt aber deren Aufkommen und verstärkt damit das Übergewicht von Lohn- und Umsatzsteuer. Für einzelne Erben (Eigenheim) entlastend; rechtlich einfach umsetzbar.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=15', null, 'belegt', '2026-10-22', false, true, 'blind', null),
  (10798, 42, 15, null, 'Einkommensteuer-Freibeträge an die Inflation koppeln (indexieren)', '{4201}', 10759, 3, 3, null, 'Setzt direkt an der kalten Progression an; Schweiz, USA, Kanada, Belgien u. a. indexieren automatisch, Simulationen zeigen weitgehenden Ausgleich. Dagegen: Einnahmeausfall gegenüber Status quo und weniger Budgetspielraum; einfaches Bundesgesetz mit Bundesratszustimmung.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=59', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2016/heft/10/beitrag/moeglichkeiten-zur-kompensation-der-kalten-progression-wirkung-in-oesterreich.html', 'belegt', '2026-10-22', false, true, 'blind', null),
  (10799, 42, 15, null, 'Einkommensteuer-Grundfreibetrag auf 15.000 Euro erhöhen', '{4201}', 10760, 2, 1, null, 'Entlastet alle Steuerpflichtigen spürbar und gleicht aufgelaufene kalte Progression mehr als aus. Dagegen: einmaliger Schritt ohne dauerhafte Anpassung und Ausfälle in zweistelliger Milliardenhöhe ohne geklärte Gegenfinanzierung.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=59', null, 'belegt', '2026-10-22', false, true, 'blind', null),
  (10800, 42, 15, null, 'Beitragszahlungen an die EU drastisch senken', '{4202}', null, 1, 1, null, 'Geringere EU-Beiträge würden den Bundeshaushalt entlasten. Dagegen: Finanzrahmen und Eigenmittel erfordern einstimmige EU-Beschlüsse, Rückflüsse aus EU-Programmen fielen ebenfalls weg.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=55', null, 'offen', '2026-10-22', false, true, 'blind', null),
  (10801, 42, 15, null, 'Schuldenbremse einhalten, keine Aufweichung', '{4202}', 10763, 2, 3, null, 'Fiskalregeln gehen laut IWF mit niedrigeren Defiziten einher, besonders bei verbindlicher Ausgestaltung. Dagegen: kausaler Effekt umstritten, Regeln drücken oft Investitionen; geltendes Recht, daher leicht umsetzbar.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=55', 'https://www.imf.org/-/media/files/publications/sdn/2018/sdn1804-on-second-generation-fiscal-rules.pdf.md', 'gemischt', '2026-10-22', false, true, 'blind', null),
  (10802, 42, 15, null, 'Erbschaftsteuer und Vermögensteuer abschaffen', '{4203}', null, 0, 1, null, 'Setzt an vermögensbezogenen Steuern an, senkt deren Anteil aber weiter und verstärkt das Übergewicht von Lohn- und Umsatzsteuer. Länder verlören ihr Erbschaftsteueraufkommen ohne geklärten Ausgleich.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=61', null, 'belegt', '2026-10-22', false, true, 'blind', null),
  (10803, 42, 16, null, 'Einkommen bis zu einer festen Grenze im Jahr steuerfrei stellen (Grundfreibetrag)', '{4201}', 10760, 2, 1, null, 'Entlastet alle Steuerpflichtigen spürbar und gleicht aufgelaufene kalte Progression mehr als aus. Dagegen: einmaliger Schritt ohne dauerhafte Anpassung und Ausfälle in zweistelliger Milliardenhöhe ohne geklärte Gegenfinanzierung.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=11', null, 'belegt', '2026-10-22', false, true, 'blind', null),
  (10804, 42, 16, null, 'Einkommensteuertarif umgestalten: niedrige Einkommen weniger, hohe Einkommen stärker belasten', '{4201}', 10762, 2, 2, null, 'Senkt die Belastung der Mehrheit der Beschäftigten und ist teilweise gegenfinanziert. Dagegen: keine dauerhafte Inflationsanpassung, Ausweichreaktionen hoher Einkommen mindern die Gegenfinanzierung.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=11', null, 'gemischt', '2026-10-22', false, true, 'blind', null),
  (10805, 42, 16, null, 'Schuldenbremse abschaffen, damit öffentliche Investitionen über Kredite finanziert werden können', '{4202}', 10764, 1, 1, null, 'Kann Investitionsstau abbauen und Wachstum stützen; IWF verweist auf Investitionsverdrängung durch starre Regeln. Dagegen: erhöht Defizit und Zinslast unmittelbar; erfordert Grundgesetzänderung mit Zweidrittelmehrheit, EU-Regeln gelten weiter.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=13', 'https://www.imf.org/-/media/files/publications/sdn/2018/sdn1804-on-second-generation-fiscal-rules.pdf.md', 'gemischt', '2026-10-22', false, true, 'blind', null),
  (10806, 42, 16, null, 'Vermögensteuer wieder einführen (mit Freibetrag, progressiver Satz)', '{4203}', 10768, 2, 2, null, 'Erhöht den Anteil vermögensbezogener Steuern; DIW schätzt je nach Ausgestaltung zweistellige Milliardenbeträge. Dagegen: Ausweichreaktionen, Bewertungsaufwand und Verfassungsvorgaben zur Bewertung; Aufkommen fließt den Ländern zu.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=10', 'https://www.diw.de/de/diw_01.c.1002952.de/nachrichten/es_gibt_bessere_wege__vermoegen_zu_besteuern.html', 'gemischt', '2026-10-22', false, true, 'blind', null),
  (10807, 42, 16, null, 'Einmalige Vermögensabgabe für die Reichsten zur Finanzierung der Krisen- und Transformationskosten', '{4202}', null, 2, 1, null, 'Einmalige Vermögensabgabe kann hohe Einnahmen bringen und Kreditbedarf senken. Dagegen: Grundgesetz erlaubt sie nur bei außerordentlichem Finanzbedarf, Bewertung und Ausweichen schwierig, Aufkommen unsicher.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=11', null, 'gemischt', '2026-10-22', false, true, 'blind', null),
  (10808, 42, 16, null, 'Übergewinnsteuer von 90 Prozent auf Krisenprofite einführen', '{4202}', null, 1, 1, null, 'Kann in Krisen zusätzliche Einnahmen bringen. Dagegen: Abgrenzung von Krisengewinnen schwierig, 90 Prozent verfassungsrechtlich heikel, EU-Solidaritätsbeitrag 2022 brachte weniger als erwartet.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=12', null, 'gemischt', '2026-10-22', false, true, 'blind', null),
  (10809, 42, 16, null, 'Steuerhinterziehung konsequent verfolgen, Strafverfolger und Finanzämter personell und technisch stärken', '{4202}', 10767, 2, 2, null, 'Betriebsprüfer erzielen im Schnitt rund 1 Mio. Euro Mehrergebnis je Jahr, mehr Personal erhöht die Einnahmen. Dagegen: Finanzämter sind Ländersache, Fachkräfte fehlen; der Bund kann nur über Gesetze, Bundesbehörden und Vereinbarungen beitragen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=13', 'https://www.zdfheute.de/wirtschaft/kampf-gegen-steuerhinterziehung-finanzamt-100.html', 'belegt', '2026-10-22', false, true, 'blind', null),
  (10810, 42, 16, null, 'Finanztransaktionssteuer von 0,1 Prozent auf jede Finanztransaktion', '{4203}', 10771, 1, 2, null, 'Besteuert bisher steuerfreie Kapitaltransaktionen; Frankreich und Italien erheben sie. Dagegen: dortige Einnahmen blieben unter den Prognosen, Handel weicht aus; national einführbar, Bemessungsgrundlage strittig.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=12', 'https://articlegateway.com/index.php/JAF/article/view/6562', 'gemischt', '2026-10-22', false, true, 'blind', null),
  (10811, 42, 16, null, 'Grunderwerbsteuer so reformieren, dass Teilkäufe von Immobilien anteilig besteuert werden', '{4203}', null, 1, 3, null, 'Erschwert Share Deals und erhöht das Aufkommen einer vermögensbezogenen Steuer. Dagegen: seit 2021 bereits verschärft, Mehreinnahmen begrenzt und den Ländern zufließend.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=11', null, 'offen', '2026-10-22', false, true, 'blind', null),
  (10812, 42, 16, null, 'Grundsteuer am Verkehrswert ausrichten und nicht auf Mieter umlegen', '{4203}', null, 1, 2, null, 'Verkehrswertorientierung stärkt die Grundsteuer als vermögensbezogene Steuer, Umlageverbot verlagert Last auf Eigentümer. Dagegen: Reform eher aufkommensneutral, Länder haben Abweichungsrecht, Bewertung aufwendig.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=10', null, 'offen', '2026-10-22', false, true, 'blind', null),
  (10813, 42, 17, null, 'Einkommen bis 7500 Euro brutto steuerlich entlasten', '{4201}', null, 1, 2, null, 'Senkt die Steuerlast für die große Mehrheit der Beschäftigten. Dagegen: Umfang und Tarifverlauf unbestimmt, keine dauerhafte Inflationsanpassung, Finanzierung offen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=16', null, 'gemischt', '2026-10-22', false, true, 'blind', null),
  (10814, 42, 17, null, 'Steuerlichen Grundfreibetrag deutlich erhöhen, orientiert an der Armutsgefährdungsschwelle', '{4201}', 10760, 2, 1, null, 'Entlastet alle Steuerpflichtigen spürbar und gleicht aufgelaufene kalte Progression mehr als aus. Dagegen: einmaliger Schritt ohne dauerhafte Anpassung und Ausfälle in zweistelliger Milliardenhöhe ohne geklärte Gegenfinanzierung.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=17', null, 'belegt', '2026-10-22', false, true, 'blind', null),
  (10815, 42, 17, null, 'Spitzensteuersatz erst bei sehr hohen Einkommen ansetzen', '{4201}', 10761, 2, 1, null, 'Mildert den steilen Progressionsverlauf bei mittleren Einkommen, an dem die kalte Progression besonders wirkt. Dagegen: einmalige Änderung ohne Indexierung, Entlastung absolut v. a. bei höheren Einkommen, hohe Ausfälle ohne Finanzierung.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=17', null, 'gemischt', '2026-10-22', false, true, 'blind', null),
  (10816, 42, 17, null, 'Vermögensteuer ab 25 Mio. Euro Vermögen mit 1 bis 3 Prozent wieder einführen', '{4203}', 10768, 2, 2, null, 'Erhöht den Anteil vermögensbezogener Steuern; DIW schätzt je nach Ausgestaltung zweistellige Milliardenbeträge. Dagegen: Ausweichreaktionen, Bewertungsaufwand und Verfassungsvorgaben zur Bewertung; Aufkommen fließt den Ländern zu.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=17', 'https://www.diw.de/de/diw_01.c.1002952.de/nachrichten/es_gibt_bessere_wege__vermoegen_zu_besteuern.html', 'gemischt', '2026-10-22', false, true, 'blind', null),
  (10817, 42, 17, null, 'Vererbte Vermögen oberhalb der Freibeträge gleich besteuern', '{4203}', 10769, 2, 3, null, 'Große Betriebsvermögen werden weitgehend steuerfrei übertragen, Schätzungen nennen Ausfälle in Milliardenhöhe; Stundung kann Liquiditätsprobleme mildern. Dagegen: Unternehmensverbände warnen vor Investitionsfolgen, Ausweichgestaltungen möglich.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=17', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2016/heft/6/beitrag/die-demontage-der-erbschaftsteuer.html', 'gemischt', '2026-10-22', false, true, 'blind', null),
  (10818, 42, 17, null, 'Finanztransaktionssteuer auf Wertpapier- und Derivategeschäfte einführen', '{4203}', 10771, 1, 2, null, 'Besteuert bisher steuerfreie Kapitaltransaktionen; Frankreich und Italien erheben sie. Dagegen: dortige Einnahmen blieben unter den Prognosen, Handel weicht aus; national einführbar, Bemessungsgrundlage strittig.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=17', 'https://articlegateway.com/index.php/JAF/article/view/6562', 'gemischt', '2026-10-22', false, true, 'blind', null),
  (10819, 42, 17, null, 'Familien beim ersten selbstgenutzten Eigenheim von der Grunderwerbsteuer befreien', '{4203}', null, 0, 2, null, 'Entlastet Ersterwerber laut IW deutlich, senkt aber das Aufkommen einer vermögensbezogenen Steuer und verstärkt so das Gewicht von Lohn- und Umsatzsteuer. Aufkommen und Satzhoheit liegen bei den Ländern, Ausgleich nötig.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=17', 'https://www.iwkoeln.de/studien/gutachten/beitrag/tobias-hentze-bjoern-seipelt-michael-voigtlaender-reform-der-grunderwerbsteuer-325128.html', 'belegt', '2026-10-22', false, true, 'blind', null),
  (10820, 42, 17, null, 'Belastungsmoratorium bei der Grundsteuer für Eigenheimbesitzer und Mieter', '{4203}', null, 0, 1, null, 'Bremst Mehrbelastungen bei der Grundsteuer, senkt aber das Aufkommen einer vermögensbezogenen Steuer. Hebesätze legen Kommunen fest, Länder haben Abweichungsrecht; der Bund kann kaum allein handeln.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=17', null, 'offen', '2026-10-22', false, true, 'blind', null),
  (10821, 42, 17, null, 'Investitionen in Infrastruktur aus der Schuldenbremse ausklammern', '{4202}', 10764, 1, 1, null, 'Kann Investitionsstau abbauen und Wachstum stützen; IWF verweist auf Investitionsverdrängung durch starre Regeln. Dagegen: erhöht Defizit und Zinslast unmittelbar; erfordert Grundgesetzänderung mit Zweidrittelmehrheit, EU-Regeln gelten weiter.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=15', 'https://www.imf.org/-/media/files/publications/sdn/2018/sdn1804-on-second-generation-fiscal-rules.pdf.md', 'gemischt', '2026-10-22', false, true, 'blind', null),
  (10822, 42, 17, null, 'Teure Beraterverträge im Militärbereich beenden, volle Transparenz über Militärausgaben', '{4202}', null, 1, 3, null, 'Weniger externe Berater und mehr Transparenz können Ausgaben senken. Dagegen: Einsparvolumen gemessen am Defizit gering, eigenes Fachpersonal muss teils erst aufgebaut werden.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=6', null, 'offen', '2026-10-22', false, true, 'blind', null),
  (10823, 42, 17, null, 'Rüstungsindustrie zur Haftung für Kostensteigerungen und Verzögerungen verpflichten', '{4202}', null, 1, 2, null, 'Bundesrechnungshof: wegen schwacher Verträge konnte die Bundeswehr Mehrkosten nicht dem Auftragnehmer anlasten. Dagegen: Hersteller preisen Risiken ein, wenige Anbieter, Wirkung erst bei neuen Verträgen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=6', 'https://vergabeblog.de/2018-04-25/bundesrechnungshof-ruegt-unwirtschaftliches-verhalten-in-den-bereichen-gesundheit-steuern-bundeswehr-und-strassenbau/', 'offen', '2026-10-22', false, true, 'blind', null),
  (10824, 42, 17, null, 'Verwaltung soll Open-Source-Lösungen statt teurer Software-Rahmenverträge einsetzen', '{4202}', null, 1, 2, null, 'Kann Lizenzkosten senken; München meldete Einsparungen in Millionenhöhe. Dagegen: Umstellung kostet zunächst, München kehrte zu Windows zurück, Einsparungen gemessen am Bundesdefizit gering.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=43', 'https://www.computerworld.com/article/1398642/switch-to-open-source-successfully-completed-city-of-munich-says.html', 'gemischt', '2026-10-22', false, true, 'blind', null);

